styleChange:
/* V2 photograph: preserve clear face/ball; confine the text fade to the left. */
.b46mp-photo{left:auto;right:0;width:auto;height:100%;max-width:none;object-fit:contain;object-position:right top}
.b46mp-card::before{background:linear-gradient(90deg,rgba(3,24,15,.98) 0%,rgba(5,33,21,.95) 30%,rgba(7,39,25,.65) 49%,rgba(8,39,26,0) 65%)}
.b46mp-card::after{background:none}
.b46mp-card[data-b46mp-theme="light"]::before{background:linear-gradient(90deg,rgba(247,252,243,1) 0%,rgba(242,249,235,.99) 30%,rgba(237,247,232,.78) 49%,rgba(239,249,235,0) 65%)}
.b46mp-card[data-b46mp-theme="light"]::after{background:none}
